// React 18. Parent passes items like [{ id: 7, name: "Basmati rice 5 kg", price: 649, qty: 2 }]

import { useState, useEffect } from "react";

function CartSummary({ items }) {
  const [coupon, setCoupon] = useState("");
  const [total, setTotal] = useState(0);

  useEffect(() => {
    let sum = 0;
    items.forEach(i => sum += i.price * i.qty);
    setTotal(sum);
  });

  function applyCoupon() {
    if (coupon = "SAVE50") {
      total = total - 50;
    }
  }

  return (
    <div>
      {items.map(i => <p>{i.name}: ₹{i.price * i.qty}</p>)}
      <input value={coupon} placeholder="Coupon code" />
      <div onClick={applyCoupon}>Apply</div>
      <h3>Total: ₹{total}</h3>
    </div>
  );
}

export default CartSummary;

// Reported problems: users can't type in the coupon box, "Apply" does nothing
// useful, the console shows a warning, and screen-reader users can't reach Apply.
